import {validAbilityAsset} from './ability-assets.js';

export function renderAbilitySetEditor(element,doc,files,hooks){
 const document=element.ownerDocument,make=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
 const edit=fn=>{try{const next=structuredClone(doc.data);fn(next);if(!validAbilityAsset('abilityset',next))throw Error('속성 이름·기본값·최솟값·최댓값과 능력 목록을 확인하세요.');if(JSON.stringify(next)===JSON.stringify(doc.data))return;hooks.before();doc.data=next;hooks.change();}catch(error){hooks.error(error.message);}renderAbilitySetEditor(element,doc,files,hooks);};
 element.replaceChildren();const heading=make('header');heading.className='asset-editor-heading';heading.append(make('h2','속성·능력 세트 · '+doc.data.name));const body=make('div');body.className='ability-set-editor asset-form';element.append(heading,body);
 const attributes=make('section'),bar=make('div'),add=make('button','속성 추가');bar.className='form-section-heading';add.dataset.addAttribute='';add.onclick=()=>edit(data=>{let i=1;while(data.attributes.some(a=>a.name==='Attribute'+i))i++;data.attributes.push({name:'Attribute'+i,base:100,min:0,max:100});});bar.append(make('h3','속성 · '+doc.data.attributes.length),add);attributes.append(bar);
 const table=make('table'),head=make('thead'),header=make('tr');for(const name of ['이름','기본값','최솟값','최댓값','']){const th=make('th',name);th.scope='col';header.append(th);}head.append(header);const rows=make('tbody');table.append(head,rows);attributes.append(table);body.append(attributes);
 doc.data.attributes.forEach((row,index)=>{const tr=make('tr');tr.dataset.attributeIndex=index;for(const key of ['name','base','min','max']){const td=make('td'),input=make('input');input.type=key==='name'?'text':'number';input.step='any';input.value=row[key];input.dataset.attributeField=key;input.setAttribute('aria-label',row.name+' '+{name:'이름',base:'기본값',min:'최솟값',max:'최댓값'}[key]);input.onchange=()=>edit(data=>data.attributes[index][key]=key==='name'?input.value:Number(input.value));td.append(input);tr.append(td);}const td=make('td'),remove=make('button','삭제');remove.setAttribute('aria-label',row.name+' 삭제');remove.onclick=()=>edit(data=>data.attributes.splice(index,1));td.append(remove);tr.append(td);rows.append(tr);});
 const abilities=make('section'),title=make('div'),select=make('select'),grant=make('button','능력 추가');title.className='form-section-heading';select.dataset.startingAbility='';select.setAttribute('aria-label','추가할 시작 능력');for(const f of files.filter(f=>f.kind==='ability'&&!doc.data.abilities.includes(f.path))){const option=make('option',f.name);option.value=f.path;select.append(option);}grant.dataset.addStartingAbility='';grant.disabled=!select.options.length;grant.onclick=()=>edit(data=>data.abilities.push(select.value));title.append(make('h3','시작 능력 · '+doc.data.abilities.length),select,grant);abilities.append(title);doc.data.abilities.forEach((asset,index)=>{const row=make('div'),name=make('button',files.find(f=>f.path===asset)?.name||asset),remove=make('button','삭제');row.className='ability-set-reference';name.title=asset;name.onclick=()=>hooks.openAsset?.(asset);remove.onclick=()=>edit(data=>data.abilities.splice(index,1));row.append(name,remove);abilities.append(row);});body.append(abilities);
 const tags=make('label','시작 태그'),input=make('input');input.value=doc.data.grantedTags.join(', ');input.setAttribute('aria-label','시작 태그');input.onchange=()=>edit(data=>data.grantedTags=[...new Set(input.value.split(',').map(v=>v.trim()).filter(Boolean))]);tags.append(input);body.append(tags);
}
